<template>
  <main class="builder-page">
    <section class="builder-shell">
      <div class="builder-heading"><div><p class="kicker">UMS INTERNAL TOOL</p><h1>Email Campaign Builder</h1><p>Featured machines are selected automatically. Reorder them, add a campaign price or POR, edit the email-only AdvSpec, save your work, copy the finished HTML into Brevo, or send the same layout directly to one contact without adding them to Brevo.</p></div><div class="count">{{ selectedMachines.length }} selected</div></div>
      <section class="controls"><label>Campaign headline<input v-model="headline" type="text" /></label><div class="actions"><button type="button" @click="resetFeatured">Reload Featured</button><button type="button" @click="saveCampaign">{{ saveLabel }}</button><button type="button" class="primary" @click="copyHtml">{{ copyLabel }}</button></div></section>
      <section class="direct-send">
        <div class="direct-send-heading">
          <div>
            <p class="kicker">ONE-OFF EMAIL</p>
            <h2>Send Directly to One Contact</h2>
            <p>Use the same selected machines and layout, but send it as a normal one-to-one email. The recipient is not added to Brevo.</p>
          </div>
          <div class="auth-actions"><span class="auth-badge" :class="{ready:authorized}">{{ authorized ? 'Ready to send' : 'Login required' }}</span><button v-if="authorized" type="button" class="logout-button" @click="logoutBuilder">Log out</button></div>
        </div>
        <div v-if="!authConfigured" class="setup-warning">Direct sending is built, but the private Email Builder password still needs to be added in Vercel.</div>
        <div v-else-if="!authorized" class="login-row">
          <label>Email Builder password<input v-model="builderPassword" type="password" autocomplete="current-password" @keyup.enter="loginBuilder" /></label>
          <button type="button" class="primary" :disabled="authBusy" @click="loginBuilder">{{ authBusy ? 'Checking…' : 'Unlock Direct Send' }}</button>
          <span v-if="authMessage" class="status-message error">{{ authMessage }}</span>
        </div>
        <div v-else class="recipient-grid">
          <label>Recipient name<input v-model="recipientName" type="text" placeholder="John Smith" /></label>
          <label>Recipient email<input v-model="recipientEmail" type="email" placeholder="john@example.com" /></label>
          <label class="subject-field">Subject<input v-model="emailSubject" type="text" /></label>
          <label class="direct-personal-message">Personal message to recipient <span>This appears directly below the campaign headline in the email.</span><textarea v-model="intro" rows="4" placeholder="Hi Michael, take a look at these machines currently available and let us know if you have an interest. Thanks, Jon Lester" /></label>
          <div class="send-actions">
            <button type="button" class="primary send-button" :disabled="sending || !canSend" @click="sendDirectEmail">{{ sending ? 'Sending…' : 'Send Email' }}</button>
            <span v-if="sendMessage" class="status-message" :class="{success:sendSuccess,error:!sendSuccess}">{{ sendMessage }}</span>
          </div>
        </div>
      </section>
      <section class="workspace">
        <div class="machine-picker"><h2>Campaign Machines</h2><p class="help">Drag to reorder. Price and AdvSpec changes here are for this email only. Use Save Campaign to keep your work for later.</p><div v-for="(machine,index) in selectedMachines" :key="machine.InvID" class="selected-row" draggable="true" @dragstart="dragIndex=index" @dragover.prevent @drop="dropAt(index)"><div class="selected-top"><span class="drag">☰</span><div class="row-copy"><strong>{{ machineTitle(machine) }}</strong><small>Stock #{{ machine.InvID }}</small></div><button type="button" class="remove" @click="removeMachine(machine.InvID)">Remove</button></div><label class="price-label">Email price<input v-model="priceText[machine.InvID]" type="text" placeholder="POR or $49,500" /></label><label class="spec-label">Email AdvSpec<textarea v-model="specText[machine.InvID]" rows="3" /></label></div><details><summary>Add another active machine</summary><input v-model="search" class="search" type="search" placeholder="Search stock #, manufacturer or model" /><button v-for="machine in availableMachines" :key="machine.InvID" type="button" class="add-row" @click="addMachine(machine)">+ {{ machineTitle(machine) }} — #{{ machine.InvID }}</button></details></div>
        <div class="preview-wrap">
          <div class="preview-toolbar">
            <div class="preview-label">EMAIL PREVIEW</div>
            <div class="preview-mode">
              <button type="button" :class="{active:previewMode==='brevo'}" @click="previewMode='brevo'">Brevo Campaign</button>
              <button type="button" :class="{active:previewMode==='direct'}" @click="previewMode='direct'">Direct Email</button>
            </div>
          </div>
          <div class="preview-note">{{ previewMode==='brevo' ? 'Brevo version includes preference and unsubscribe links.' : 'Direct email version does not include Brevo preference or unsubscribe links.' }}</div>
          <div class="email-preview"><div class="email-header"><img src="/Images/ums-logo.png" alt="Used Machinery Source" class="email-logo" /><div class="contact-links"><a href="tel:+12569801200">(256) 980-1200</a><span>•</span><a href="mailto:jon@usedms.com">jon@usedms.com</a><span>•</span><a href="https://usedmachinerysource.com" target="_blank">usedmachinerysource.com</a></div></div><div class="email-intro"><h2>{{ headline }}</h2><p>{{ intro }}</p></div><div class="machine-grid"><article v-for="machine in selectedMachines" :key="machine.InvID" class="email-machine"><img v-if="machineImages[machine.InvID]" :src="imageUrl(machine.InvID)" :alt="machineTitle(machine)" /><div class="email-machine-copy"><h3>{{ machineTitle(machine) }}</h3><p class="type">{{ webDescription(machine) }}</p><p class="stock"><strong>Stock #{{ machine.InvID }}</strong></p><p class="price">{{ priceText[machine.InvID] || 'POR' }}</p><p class="spec">{{ specText[machine.InvID] }}</p><a :href="machineUrl(machine)" target="_blank">LEARN MORE</a></div></article><article class="sell-callout" :class="{wide:selectedMachines.length%2===0}"><div><h3>HAVE MACHINERY TO SELL OR TRADE?</h3><p>Planning a new equipment purchase or have surplus machinery you no longer need?</p><p><strong>Used Machinery Source may be able to get you a better offer for your equipment.</strong> We’re also happy to work directly with your OEM distributor to help facilitate a trade-in.</p><a href="https://usedmachinerysource.com/sell-your-machine" target="_blank">TELL US ABOUT YOUR MACHINE</a></div></article></div><div class="email-footer"><strong>Used Machinery Source, LLC</strong><br />Florence, Alabama<br /><a href="https://usedmachinerysource.com/equipment">View Current Inventory</a><div class="social-links"><a href="https://www.facebook.com/UsedMachinerySource" target="_blank">Facebook</a><span>•</span><a href="https://www.youtube.com/@UsedMachinerySource" target="_blank">YouTube</a></div><div v-if="previewMode==='brevo'" class="preference-footer"><strong>Want to see different machinery?</strong><p>Update your email preferences to choose the types of machines and brands you'd like to hear about.</p><span class="preference-button">UPDATE EMAIL PREFERENCES</span><p class="unsubscribe-copy">Don't want to receive emails from us? <span>Unsubscribe</span></p></div></div></div></div>
      </section>
    </section>
  </main>
</template>
<script setup>
import machinesData from '~/assets/data/machines.json'
useHead({title:'UMS Email Campaign Builder',meta:[{name:'robots',content:'noindex,nofollow'}]})
const DEFAULT_HEADLINE='Featured Machinery Available Now',DEFAULT_INTRO='Take a look at these machines currently available through Used Machinery Source. Contact us for additional information, pricing, or to arrange an inspection.',STORAGE_KEY='ums-email-builder-campaign-v1'
const headline=ref(DEFAULT_HEADLINE),intro=ref(DEFAULT_INTRO)
const selectedMachines=ref([]),machineImages=ref({}),priceText=ref({}),specText=ref({}),dragIndex=ref(null),search=ref(''),copyLabel=ref('Copy HTML for Brevo'),saveLabel=ref('Save Campaign')
const recipientName=ref(''),recipientEmail=ref(''),emailSubject=ref('Machinery Available from Used Machinery Source'),previewMode=ref('direct')
const authConfigured=ref(false),authorized=ref(false),builderPassword=ref(''),authBusy=ref(false),authMessage=ref('')
const sending=ref(false),sendMessage=ref(''),sendSuccess=ref(false)
const canSend=computed(()=>authorized.value&&selectedMachines.value.length>0&&recipientEmail.value.trim()&&emailSubject.value.trim())
const offMarketValue=m=>m.OffMarket??m.Off_Market??0,webDescription=m=>m.WebDesc||m.Web_Desc||'',advertisingSpec=m=>m.AdvSpec||m.Adv_Spec||'',machineTitle=m=>[m.Year,m.Manufacturer,m.Model].filter(Boolean).join(' ')
const slug=m=>`${m.Manufacturer||''}-${m.Model||''}`.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,''),machineUrl=m=>`https://usedmachinerysource.com/equipment/${m.InvID}/${slug(m)}`,imageUrl=id=>`https://usedmachinerysource.com/Images/${machineImages.value[id]}`
const activeMachines=computed(()=>machinesData.filter(m=>Number(m.Sold)===0&&Number(offMarketValue(m))===0&&Number(m.dont_advertise)===0)),availableMachines=computed(()=>{const chosen=new Set(selectedMachines.value.map(m=>String(m.InvID))),q=search.value.trim().toLowerCase();return activeMachines.value.filter(m=>!chosen.has(String(m.InvID))).filter(m=>!q||`${m.InvID} ${m.Manufacturer} ${m.Model} ${webDescription(m)}`.toLowerCase().includes(q)).slice(0,20)})
function ensureEmailFields(m){if(!(m.InvID in priceText.value))priceText.value[m.InvID]='POR';if(!(m.InvID in specText.value))specText.value[m.InvID]=advertisingSpec(m)}
async function loadImage(m){if(machineImages.value[m.InvID])return;try{const files=await $fetch('/api/images',{query:{invID:m.InvID}});if(files?.length)machineImages.value[m.InvID]=files[0]}catch(e){console.error(`Could not load image for ${m.InvID}`,e)}}
async function resetFeatured(){headline.value=DEFAULT_HEADLINE;intro.value=DEFAULT_INTRO;priceText.value={};specText.value={};selectedMachines.value=activeMachines.value.filter(m=>Number(m.Featured)===1);for(const m of selectedMachines.value){ensureEmailFields(m);await loadImage(m)}}
async function addMachine(m){selectedMachines.value.push(m);ensureEmailFields(m);search.value='';await loadImage(m)}
function removeMachine(id){selectedMachines.value=selectedMachines.value.filter(m=>String(m.InvID)!==String(id))}
function dropAt(index){if(dragIndex.value===null||dragIndex.value===index)return;const next=[...selectedMachines.value],[moved]=next.splice(dragIndex.value,1);next.splice(index,0,moved);selectedMachines.value=next;dragIndex.value=null}
function saveCampaign(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify({headline:headline.value,intro:intro.value,machineIds:selectedMachines.value.map(m=>m.InvID),prices:priceText.value,specs:specText.value,savedAt:new Date().toISOString()}));saveLabel.value='Saved!';setTimeout(()=>saveLabel.value='Save Campaign',2200)}catch{saveLabel.value='Save failed'}}
async function loadSavedCampaign(){try{const raw=localStorage.getItem(STORAGE_KEY);if(!raw)return false;const saved=JSON.parse(raw),byId=new Map(activeMachines.value.map(m=>[String(m.InvID),m]));headline.value=saved.headline||DEFAULT_HEADLINE;intro.value=saved.intro||DEFAULT_INTRO;priceText.value=saved.prices||{};specText.value=saved.specs||{};selectedMachines.value=(saved.machineIds||[]).map(id=>byId.get(String(id))).filter(Boolean);for(const m of selectedMachines.value){ensureEmailFields(m);await loadImage(m)}return true}catch(e){console.error('Could not load saved campaign',e);return false}}
function esc(v=''){return String(v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;')}
function machineCell(m){const img=machineImages.value[m.InvID]?`<img src="${imageUrl(m.InvID)}" alt="${esc(machineTitle(m))}" width="180" style="display:block;width:180px;max-width:100%;height:auto;border:0;margin:0 auto 14px;">`:'';const price=esc(priceText.value[m.InvID]||'POR'),spec=esc(specText.value[m.InvID]??advertisingSpec(m)).replace(/\n/g,'<br>');return `<td width="50%" valign="top" style="width:50%;padding:8px;"><table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" style="background:#f4f7fb;border:2px solid #9fb4d3;"><tr><td style="padding:16px;text-align:center;font-family:Arial,sans-serif;">${img}<h2 style="margin:0 0 6px;font-size:19px;line-height:1.2;color:#1c4587;">${esc(machineTitle(m))}</h2><p style="margin:0 0 7px;font-size:13px;line-height:1.35;color:#434343;">${esc(webDescription(m))}</p><p style="margin:0 0 7px;font-size:13px;color:#222;"><strong>Stock #${esc(m.InvID)}</strong></p><p style="margin:0 0 10px;font-size:18px;font-weight:bold;color:#1c4587;">${price}</p><p style="margin:0 0 14px;font-size:13px;line-height:1.4;color:#333;">${spec}</p><a href="${machineUrl(m)}" style="display:inline-block;background:#1c4587;color:#fff;text-decoration:none;font-weight:bold;font-size:12px;padding:10px 14px;">LEARN MORE</a></td></tr></table></td>`}
const sellInner=`<table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" style="background:#1c4587;border:2px solid #16386e;"><tr><td style="padding:20px;text-align:center;font-family:Arial,sans-serif;color:#fff;"><h2 style="margin:0 0 8px;font-size:20px;line-height:1.2;color:#fff;">HAVE MACHINERY TO SELL OR TRADE?</h2><p style="margin:0 0 9px;font-size:13px;line-height:1.4;color:#fff;">Planning a new equipment purchase or have surplus machinery you no longer need?</p><p style="margin:0 0 14px;font-size:13px;line-height:1.4;color:#fff;"><strong>Used Machinery Source may be able to get you a better offer for your equipment.</strong> We’re also happy to work directly with your OEM distributor to help facilitate a trade-in.</p><a href="https://usedmachinerysource.com/sell-your-machine" style="display:inline-block;background:#fff;color:#1c4587;text-decoration:none;font-weight:bold;font-size:12px;padding:10px 14px;">TELL US ABOUT YOUR MACHINE</a></td></tr></table>`
const socialFooter=`<div style="margin-top:8px;font-size:12px;"><a href="https://www.facebook.com/UsedMachinerySource" style="color:#1c4587;text-decoration:none;font-weight:bold;">Facebook</a>&nbsp;&nbsp;•&nbsp;&nbsp;<a href="https://www.youtube.com/@UsedMachinerySource" style="color:#1c4587;text-decoration:none;font-weight:bold;">YouTube</a></div>`
const preferenceFooter=`<div style="margin-top:16px;padding-top:16px;border-top:1px solid #cfcfcf;"><strong style="font-size:14px;color:#333;">Want to see different machinery?</strong><p style="margin:5px auto 11px;max-width:470px;font-size:12px;line-height:1.45;color:#666;">Update your email preferences to choose the types of machines and brands you'd like to hear about.</p><a href="{{ update_profile }}" style="display:inline-block;border:1px solid #1c4587;color:#1c4587;text-decoration:none;font-weight:bold;font-size:11px;padding:8px 12px;">UPDATE EMAIL PREFERENCES</a><p style="margin:13px 0 0;font-size:11px;line-height:1.4;color:#777;">Don't want to receive emails from us? <a href="{{ unsubscribe }}" style="color:#666;text-decoration:underline;">Unsubscribe</a></p></div>`
function buildEmailHtml(includeBrevoFooter=true){let rows='',n=selectedMachines.value.length;for(let i=0;i<n;i+=2){const left=machineCell(selectedMachines.value[i]);if(selectedMachines.value[i+1])rows+=`<tr>${left}${machineCell(selectedMachines.value[i+1])}</tr>`;else rows+=`<tr>${left}<td width="50%" valign="top" style="width:50%;padding:8px;">${sellInner}</td></tr>`}if(n%2===0)rows+=`<tr><td colspan="2" style="padding:8px;">${sellInner}</td></tr>`;return `<!doctype html><html><body style="margin:0;padding:0;background:#eceff3;"><table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" style="background:#eceff3;"><tr><td align="center" style="padding:24px 10px;"><table role="presentation" width="600" cellspacing="0" cellpadding="0" border="0" style="width:100%;max-width:600px;background:#f5f5f5;"><tr><td style="background:#fff;padding:0 20px 2px;text-align:center;font-family:Arial,sans-serif;border-bottom:1px solid #d9dee7;"><img src="https://usedmachinerysource.com/Images/ums-logo.png" alt="Used Machinery Source" width="300" style="display:block;width:300px;max-width:90%;height:auto;border:0;margin:0 auto -14px;"><div style="font-size:12px;line-height:1.15;color:#434343;margin-top:-6px;"><a href="tel:+12569801200" style="color:#1c4587;text-decoration:none;font-weight:bold;">(256) 980-1200</a>&nbsp;&nbsp;•&nbsp;&nbsp;<a href="mailto:jon@usedms.com" style="color:#1c4587;text-decoration:none;font-weight:bold;">jon@usedms.com</a>&nbsp;&nbsp;•&nbsp;&nbsp;<a href="https://usedmachinerysource.com" style="color:#1c4587;text-decoration:none;font-weight:bold;">usedmachinerysource.com</a></div></td></tr><tr><td style="padding:20px 24px 14px;text-align:center;font-family:Arial,sans-serif;background:#f5f5f5;"><h1 style="margin:0 0 8px;font-size:28px;color:#222;">${esc(headline.value)}</h1><p style="margin:0;font-size:16px;line-height:1.45;color:#555;">${esc(intro.value)}</p></td></tr><tr><td style="padding:0 12px 22px;background:#f5f5f5;"><table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0">${rows}</table></td></tr><tr><td style="padding:22px;text-align:center;background:#e9e9e9;font-family:Arial,sans-serif;font-size:13px;line-height:1.6;color:#555;"><strong>Used Machinery Source, LLC</strong><br>Florence, Alabama<br><a href="https://usedmachinerysource.com/equipment" style="color:#1c4587;">View Current Inventory</a>${socialFooter}${includeBrevoFooter?preferenceFooter:'' }</td></tr></table></td></tr></table></body></html>`}
async function copyHtml(){try{await navigator.clipboard.writeText(buildEmailHtml());copyLabel.value='Copied!';setTimeout(()=>copyLabel.value='Copy HTML for Brevo',2200)}catch{copyLabel.value='Copy failed'}}
async function checkBuilderAuth(){try{const status=await $fetch('/api/email-builder-status');authConfigured.value=Boolean(status?.configured);authorized.value=Boolean(status?.authorized)}catch{authConfigured.value=false;authorized.value=false}}
async function loginBuilder(){authBusy.value=true;authMessage.value='';try{await $fetch('/api/email-builder-login',{method:'POST',body:{password:builderPassword.value}});builderPassword.value='';await checkBuilderAuth();if(!authorized.value)authMessage.value='Could not unlock direct sending.'}catch(e){authMessage.value=e?.data?.statusMessage||e?.statusMessage||'Incorrect password.'}finally{authBusy.value=false}}
async function logoutBuilder(){try{await $fetch('/api/email-builder-logout',{method:'POST'})}catch(e){console.error('Could not log out Email Builder',e)}authorized.value=false;recipientName.value='';recipientEmail.value='';sendMessage.value='';sendSuccess.value=false}
function buildDirectText(){const lines=[headline.value,intro.value,''];for(const m of selectedMachines.value){lines.push(machineTitle(m),webDescription(m),`Stock #${m.InvID}`,priceText.value[m.InvID]||'POR',specText.value[m.InvID]||'',machineUrl(m),'')}lines.push('Used Machinery Source, LLC','Florence, Alabama','(256) 980-1200','jon@usedms.com','https://usedmachinerysource.com');return lines.filter(v=>v!==undefined&&v!==null).join('\n')}
async function sendDirectEmail(){if(!canSend.value||sending.value)return;sending.value=true;sendMessage.value='';sendSuccess.value=false;try{const result=await $fetch('/api/email-builder-send',{method:'POST',body:{recipientName:recipientName.value.trim(),recipientEmail:recipientEmail.value.trim(),subject:emailSubject.value.trim(),html:buildEmailHtml(false),text:buildDirectText()}});sendSuccess.value=Boolean(result?.success);sendMessage.value=sendSuccess.value?`Sent to ${recipientEmail.value.trim()}.`:'The email was not accepted.'}catch(e){if(e?.status===401){authorized.value=false;sendMessage.value='Your Email Builder login expired. Unlock Direct Send again.'}else{sendMessage.value=e?.data?.statusMessage||e?.statusMessage||'Email could not be sent.'}}finally{sending.value=false}}
onMounted(async()=>{await checkBuilderAuth();if(!(await loadSavedCampaign()))await resetFeatured()})
</script>
<style scoped>
